export class OverrideFiltersDecoder {
    public static decode(filtersJson: string): OverrideFilters {
        const filtersCsv = <{[key: string]: string}>JSON.parse(filtersJson);
        const filters = {};
        for (const [k, v] of Object.entries(filtersCsv)) {
            filters[k] = new Set<string>(v.split(",").map((s) => s.trim()));
        }

        return filters;
    }
}{noformat}

